/// مواقف وقرارات: الطفل يختار التصرف الصحيح في موقف من حياته.
class Situation {
  final String id;
  final String topic; // سلامة، أخلاق، بيت، مدرسة، مال
  final String text;
  final List<String> options;
  final int answer;
  final String why;
  const Situation(this.id, this.topic, this.text, this.options, this.answer, this.why);
}

