const kSituationTopics = ['الكل', 'سلامة', 'أخلاق', 'بيت', 'مدرسة', 'مال'];

List<Situation> situationRound(String topic, Random r, {int count = 6}) {
  final pool = topic == 'الكل' ? List.of(kSituations) : kSituations.where((s) => s.topic == topic).toList();
  pool.shuffle(r);
  return pool.take(count).toList();
}
